// Generates lib/src/bindings.g.dart from the engine's C header
// (crates/fynkel_ffi/include/fynkel.h, itself generated by cbindgen).
//
//   dart run tool/ffigen.dart
//
// CI runs this and fails when the result differs from the committed file.

import 'dart:io';

import 'package:ffigen/ffigen.dart';

/// Calls that may block or take long: they are not leaf calls, so the Dart
/// VM can collect garbage and run other isolates while they run.
const _blocking = {
  'fy_view_new_headless', // may create the GPU device, and starts a thread
  'fy_view_new_apple', // the same
  'fy_view_new_android', // the same
  'fy_view_new_apple_layer', // the same
  'fy_apple_layer_attach', // waits for a frame in progress
  'fy_apple_layer_detach', // the same
  'fy_apple_set_frame_ready', // waits for a frame-ready call in progress
  'fy_view_free', // joins the render worker
  'fy_view_read', // waits for the GPU
  'fy_mesh_new', // generating tangents takes about 1 µs per triangle
  'fy_texture_decode', // decoding a big image takes tens of milliseconds
  'fy_texture_new_rgba', // copies the pixels
  'fy_model_load', // decodes the model's images and generates tangents
  'fy_quality_auto', // may create the GPU device
  'fy_sky_image_decode', // a 2K sky takes about 8 ms
  // Shapes with many segments take tens of milliseconds, as can
  // building from a shape and working normals out again. Sweeps and
  // fy_mesh_set_positions stay leaf: they're called every frame for a
  // rope or a mesh that changes, with the game's own lists (a leaf
  // call's .address), and take under 2 ms for a 1 km road. Only a new
  // count on a mesh of a million vertices takes longer (31 ms).
  'fy_mesh_new_box',
  'fy_mesh_new_capsule',
  'fy_mesh_new_cone',
  'fy_mesh_new_cylinder',
  'fy_mesh_new_disc',
  'fy_mesh_new_grid',
  'fy_mesh_new_sphere',
  'fy_mesh_new_torus',
  'fy_mesh_extrude',
  'fy_mesh_lathe',
  'fy_mesh_combine',
  'fy_mesh_recalculate',
  'fy_particles_simulate', // up to 1800 steps
  'fy_shader_new', // parses and checks the WGSL
};

Future<void> main() async {
  final root = Platform.script.resolve('../');
  final header = root.resolve('../../crates/fynkel_ffi/include/fynkel.h');
  final generator = FfiGenerator(
    input: Input(
      entryPoints: [header],
      // Only the header's own declarations, not those of the system
      // headers it includes.
      include: (uri) => uri == header,
    ),
    output: Output(
      dart: DartOutput(path: root.resolve('lib/src/bindings.g.dart')),
      preamble:
          '// Generated by tool/ffigen.dart from crates/fynkel_ffi/include/fynkel.h. Do not edit.\n'
          '// ignore_for_file: type=lint, unused_field',
      style: const NativeExternalBindings(assetId: 'package:fynkel/fynkel'),
    ),
    visitors: [
      Visitor(
        func: (node) {
          if (!node.originalName.startsWith('fy_')) return;
          node.isIncluded = true;
          node.isLeaf = !_blocking.contains(node.originalName);
        },
        struct: (node) => node.isIncluded = node.originalName.startsWith('Fy'),
        enumClass: (node) {
          node.isIncluded = node.originalName.startsWith('Fy');
          node.style = EnumStyle.intConstants;
        },
        macroConstant: (node) => node.isIncluded = node.originalName.startsWith('FY_'),
      ),
    ],
  );
  await generator.generate();
}
